function keyOrIndex(pe: PathElement): string | undefined {
    if (pe.kind !== PathElementKind.KeyOrIndex) return undefined;
    return pe.key;
}

function pathElementEquals(a: PathElement, b: PathElement): boolean {
    if (a.kind !== b.kind) return false;

    if (a.kind === PathElementKind.Type && b.kind === PathElementKind.Type) {
        return a.index === b.index;
    }

    if (
        a.kind === PathElementKind.KeyOrIndex &&
        b.kind === PathElementKind.KeyOrIndex
    ) {
        return a.key === b.key;
    }

    return true;
}

function withRef(refOrLoc: Ref | (() => Ref) | Location): { ref: Ref };
function withRef<T extends object>(
    refOrLoc: Ref | (() => Ref) | Location,
    props?: T,
): T & { ref: Ref };
function withRef<T extends object>(
    refOrLoc: Ref | (() => Ref) | Location,
    props?: T,
): unknown {
    const ref =
        typeof refOrLoc === "function"
            ? refOrLoc()
            : refOrLoc instanceof Ref
              ? refOrLoc
              : refOrLoc.canonicalRef;
    return { ref, ...(props ?? {}) };
}

function checkJSONSchemaObject(
    x: unknown,
    refOrLoc: Ref | (() => Ref),
): StringMap {
    if (Array.isArray(x)) {
        return messageError("SchemaArrayIsInvalidSchema", withRef(refOrLoc));
    }

    if (x === null) {
        return messageError("SchemaNullIsInvalidSchema", withRef(refOrLoc));
    }

    if (typeof x !== "object") {
        return messageError(
            "SchemaInvalidJSONSchemaType",
            withRef(refOrLoc, { type: typeof x }),
        );
    }

    return x;
}

function checkJSONSchema(x: unknown, refOrLoc: Ref | (() => Ref)): JSONSchema {
    if (typeof x === "boolean") return x;
    return checkJSONSchemaObject(x, refOrLoc);
}

const numberRegexp = /^[0-9]+$/;

function normalizeURI(uri: string | URI): URI {
    // FIXME: This is overly complicated and a bit shady.  The problem is
    // that `normalize` will URL-escape, with the result that if we want to
    // open the URL as a file, escaped character will thwart us.  I think the
    // JSONSchemaStore should take a URI, not a string, and if it reads from
    // a file it can decode by itself.
    if (typeof uri === "string") {
        uri = new URI(fixWindowsPath(uri));
    }

    return new URI(URI.decode(uri.clone().normalize().toString()));
}

export class Ref {
    public static root(address: string | undefined): Ref {
        const uri = definedMap(address, (a) => new URI(fixWindowsPath(a)));
        return new Ref(uri, []);
    }

    private static parsePath(path: string): readonly PathElement[] {
        const elements: PathElement[] = [];

        if (path.startsWith("/")) {
            elements.push({ kind: PathElementKind.Root });
            path = path.slice(1);
        }

        if (path !== "") {
            const parts = path.split("/");
            parts.forEach((part) => {
                elements.push({ kind: PathElementKind.KeyOrIndex, key: part });
            });
        }

        return elements;
    }

    public static parseURI(uri: URI, destroyURI = false): Ref {
        if (!destroyURI) {
            uri = uri.clone();
        }

        let path = uri.fragment();
        uri.fragment("");
        if ((uri.host() !== "" || uri.filename() !== "") && path === "") {
            path = "/";
        }

        const elements = Ref.parsePath(path);
        return new Ref(uri, elements);
    }

    public static parse(ref: string): Ref {
        return Ref.parseURI(new URI(fixWindowsPath(ref)), true);
    }

    public addressURI: URI | undefined;

    public constructor(
        addressURI: URI | undefined,
        public readonly path: readonly PathElement[],
    ) {
        if (addressURI !== undefined) {
            assert(
                addressURI.fragment() === "",
                `Ref URI with fragment is not allowed: ${addressURI.toString()}`,
            );
            this.addressURI = normalizeURI(addressURI);
        } else {
            this.addressURI = undefined;
        }
    }

    public get hasAddress(): boolean {
        return this.addressURI !== undefined;
    }

    public get address(): string {
        return defined(this.addressURI).toString();
    }

    public get isRoot(): boolean {
        return (
            this.path.length === 1 && this.path[0].kind === PathElementKind.Root
        );
    }

    private pushElement(pe: PathElement): Ref {
        const newPath = Array.from(this.path);
        newPath.push(pe);
        return new Ref(this.addressURI, newPath);
    }

    public push(...keys: string[]): Ref {
        // eslint-disable-next-line @typescript-eslint/no-this-alias
        let ref: Ref = this;
        for (const key of keys) {
            ref = ref.pushElement({ kind: PathElementKind.KeyOrIndex, key });
        }

        return ref;
    }

    public pushObject(): Ref {
        return this.pushElement({ kind: PathElementKind.Object });
    }

    public pushType(index: number): Ref {
        return this.pushElement({ kind: PathElementKind.Type, index });
    }

    public resolveAgainst(base: Ref | undefined): Ref {
        let addressURI = this.addressURI;
        if (base?.addressURI !== undefined) {
            addressURI =
                addressURI === undefined
                    ? base.addressURI
                    : addressURI.absoluteTo(base.addressURI);
        }

        return new Ref(addressURI, this.path);
    }

    public get name(): string {
        const path = Array.from(this.path);

        for (;;) {
            const e = path.pop();
            if (e === undefined || e.kind === PathElementKind.Root) {
                let name =
                    this.addressURI !== undefined
                        ? this.addressURI.filename()
                        : "";
                const suffix =
                    this.addressURI !== undefined
                        ? this.addressURI.suffix()
                        : "";
                if (name.length > suffix.length + 1) {
                    name = name.slice(0, name.length - suffix.length - 1);
                }

                if (name === "") {
                    return "Something";
                }

                return name;
            }

            switch (e.kind) {
                case PathElementKind.KeyOrIndex:
                    if (numberRegexp.test(e.key)) {
                        return e.key;
                    }

                    break;
                case PathElementKind.Type:
                case PathElementKind.Object:
                    return panic(
                        "We shouldn't try to get the name of Type or Object refs",
                    );
                default:
                    return assertNever(e);
            }
        }
    }

    public get definitionName(): string | undefined {
        const pe = arrayGetFromEnd(this.path, 2);
        if (pe === undefined) return undefined;
        if (keyOrIndex(pe) === "definitions" || keyOrIndex(pe) === "$defs")
            return keyOrIndex(defined(arrayLast(this.path)));
        return undefined;
    }

    public toString(): string {
        function elementToString(e: PathElement): string {
            switch (e.kind) {
                case PathElementKind.Root:
                    return "";
                case PathElementKind.Type:
                    return `type/${e.index.toString()}`;
                case PathElementKind.Object:
                    return "object";
                case PathElementKind.KeyOrIndex:
                    return e.key;
                default:
                    return assertNever(e);
            }
        }

        const address =
            this.addressURI === undefined ? "" : this.addressURI.toString();
        return `${address}#${this.path.map(elementToString).join("/")}`;
    }

    private lookup(
        local: unknown,
        path: readonly PathElement[],
        root: JSONSchema,
    ): JSONSchema {
        const refMaker = (): Ref => new Ref(this.addressURI, path);
        const first = path[0];
        if (first === undefined) {
            return checkJSONSchema(local, refMaker);
        }

        const rest = path.slice(1);
        switch (first.kind) {
            case PathElementKind.Root:
                return this.lookup(root, rest, root);
            case PathElementKind.KeyOrIndex: {
                const key = first.key;
                if (Array.isArray(local)) {
                    if (!/^\d+$/.test(key)) {
                        return messageError(
                            "SchemaCannotIndexArrayWithNonNumber",
                            withRef(refMaker, { actual: key }),
                        );
                    }

                    const index = Number.parseInt(first.key, 10);
                    if (index >= local.length) {
                        return messageError(
                            "SchemaIndexNotInArray",
                            withRef(refMaker, { index }),
                        );
                    }

                    return this.lookup(local[index], rest, root);
                }

                if (!hasOwnProperty(local, key)) {
                    return messageError(
                        "SchemaKeyNotInObject",
                        withRef(refMaker, { key }),
                    );
                }

                return this.lookup(
                    checkJSONSchemaObject(local, refMaker)[first.key],
                    rest,
                    root,
                );
            }

            case PathElementKind.Type:
                return panic('Cannot look up path that indexes "type"');
            case PathElementKind.Object:
                return panic('Cannot look up path that indexes "object"');
            default:
                return assertNever(first);
        }
    }

    public lookupRef(root: JSONSchema): JSONSchema {
        return this.lookup(root, this.path, root);
    }

    public equals<R extends Ref>(other: R): boolean {
        if (!(other instanceof Ref)) return false;
        if (this.addressURI !== undefined && other.addressURI !== undefined) {
            if (!this.addressURI.equals(other.addressURI)) return false;
        } else if (
            (this.addressURI === undefined) !==
            (other.addressURI === undefined)
        )
            return false;

        const l = this.path.length;
        if (l !== other.path.length) return false;
        for (let i = 0; i < l; i++) {
            if (!pathElementEquals(this.path[i], other.path[i])) return false;
        }

        return true;
    }

    public hashCode(): number {
        let acc = hashCodeOf(definedMap(this.addressURI, (u) => u.toString()));
        for (const pe of this.path) {
            acc = addHashCode(acc, pe.kind);
            switch (pe.kind) {
                case PathElementKind.Type:
                    acc = addHashCode(acc, pe.index);
                    break;
                case PathElementKind.KeyOrIndex:
                    acc = addHashCode(acc, hashString(pe.key));
                    break;
                default:
                    break;
            }
        }

        return acc;
    }
}

class Location {
    public readonly canonicalRef: Ref;

    public readonly virtualRef: Ref;

    public constructor(
        canonicalRef: Ref,
        virtualRef?: Ref,
        public readonly haveID: boolean = false,
    ) {
        this.canonicalRef = canonicalRef;
        this.virtualRef = virtualRef ?? canonicalRef;
    }

    public updateWithID(id: string | unknown): Location {
        if (typeof id !== "string") return this;
        const parsed = Ref.parse(id);
        const virtual = this.haveID
            ? parsed.resolveAgainst(this.virtualRef)
            : parsed;
        if (!this.haveID) {
            messageAssert(
                virtual.hasAddress,
                "SchemaIDMustHaveAddress",
                withRef(this, { id }),
            );
        }

        return new Location(this.canonicalRef, virtual, true);
    }

    public push(...keys: string[]): Location {
        return new Location(
            this.canonicalRef.push(...keys),
            this.virtualRef.push(...keys),
            this.haveID,
        );
    }

    public pushObject(): Location {
        return new Location(
            this.canonicalRef.pushObject(),
            this.virtualRef.pushObject(),
            this.haveID,
        );
    }

    public pushType(index: number): Location {
        return new Location(
            this.canonicalRef.pushType(index),
            this.virtualRef.pushType(index),
            this.haveID,
        );
    }

    public toString(): string {
        return `${this.virtualRef.toString()} (${this.canonicalRef.toString()})`;
    }
}

class Canonizer {
    private readonly _map = new EqualityMap<Ref, Location>();

    private readonly _schemaAddressesAdded = new Set<string>();

    public constructor(private readonly _ctx: RunContext) {}

    private addIDs(schema: unknown, loc: Location): void {
        if (schema === null) return;
        if (Array.isArray(schema)) {
            for (let i = 0; i < schema.length; i++) {
                this.addIDs(schema[i], loc.push(i.toString()));
            }

            return;
        }

        if (typeof schema !== "object") {
            return;
        }

        const locWithoutID = loc;
        const maybeID = "$id" in schema ? schema.$id : undefined;
        if (typeof maybeID === "string") {
            loc = loc.updateWithID(maybeID);
        }

        if (loc.haveID) {
            if (this._ctx.debugPrintSchemaResolving) {
                console.log(`adding mapping ${loc.toString()}`);
            }

            this._map.set(loc.virtualRef, locWithoutID);
        }

        for (const property of Object.getOwnPropertyNames(schema)) {
            this.addIDs(
                schema[property as keyof typeof schema],
                loc.push(property),
            );
        }
    }

    public addSchema(schema: unknown, address: string): boolean {
        if (this._schemaAddressesAdded.has(address)) return false;

        this.addIDs(
            schema,
            new Location(Ref.root(address), Ref.root(undefined)),
        );
        this._schemaAddressesAdded.add(address);
        return true;
    }

    // Returns: Canonical ref
    public canonize(base: Location, ref: Ref): Location {
        const virtual = ref.resolveAgainst(base.virtualRef);
        const loc = this._map.get(virtual);
        if (loc !== undefined) {
            return loc;
        }

        const canonicalRef =
            virtual.addressURI === undefined
                ? new Ref(base.canonicalRef.addressURI, virtual.path)
                : virtual;
        return new Location(canonicalRef, new Ref(undefined, virtual.path));
    }
}

function checkTypeList(
    typeOrTypes: string | string[],
    loc: Location,
): ReadonlySet<string> {
    let set: Set<string>;
    if (typeof typeOrTypes === "string") {
        set = new Set([typeOrTypes]);
    } else if (Array.isArray(typeOrTypes)) {
        const arr: string[] = [];
        for (const t of typeOrTypes) {
            if (typeof t !== "string") {
                return messageError(
                    "SchemaTypeElementMustBeString",
                    withRef(loc, { element: t }),
                );
            }

            arr.push(t);
        }

        set = new Set(arr);
    } else {
        return messageError(
            "SchemaTypeMustBeStringOrStringArray",
            withRef(loc, { actual: typeOrTypes }),
        );
    }

    messageAssert(set.size > 0, "SchemaNoTypeSpecified", withRef(loc));
    const validTypes = [
        "null",
        "boolean",
        "object",
        "array",
        "number",
        "string",
        "integer",
    ];
    const maybeInvalid = iterableFind(set, (s) => !validTypes.includes(s));
    if (maybeInvalid !== undefined) {
        return messageError(
            "SchemaInvalidType",
            withRef(loc, { type: maybeInvalid }),
        );
    }

    return set;
}

function checkRequiredArray(arr: string[], loc: Location): string[] {
    if (!Array.isArray(arr)) {
        return messageError(
            "SchemaRequiredMustBeStringOrStringArray",
            withRef(loc, { actual: arr }),
        );
    }

    for (const e of arr) {
        if (typeof e !== "string") {
            return messageError(
                "SchemaRequiredElementMustBeString",
                withRef(loc, { element: e }),
            );
        }
    }

    return arr;
}

export const schemaTypeDict = {
    null: true,
    boolean: true,
    string: true,
    integer: true,
    number: true,
    array: true,
    object: true,
};
export type JSONSchemaType = keyof typeof schemaTypeDict;

const schemaTypes = Object.getOwnPropertyNames(
    schemaTypeDict,
) as JSONSchemaType[];

export interface JSONSchemaAttributes {
    forArray?: TypeAttributes;
    forBoolean?: TypeAttributes;
    forCases?: TypeAttributes[];
    forNull?: TypeAttributes;
    forNumber?: TypeAttributes;
    forObject?: TypeAttributes;
    forString?: TypeAttributes;
    forType?: TypeAttributes;
    forUnion?: TypeAttributes;
}
export type JSONSchemaAttributeProducer = (
    schema: JSONSchema,
    canonicalRef: Ref,
    types: Set<JSONSchemaType>,
    unionCases: JSONSchema[] | undefined,
) => JSONSchemaAttributes | undefined;

function typeKindForJSONSchemaFormat(
    format: string,
): TransformedStringTypeKind | undefined {
    const target = iterableFind(
        transformedStringTypeTargetTypeKindsMap,
        ([_, { jsonSchema }]) => jsonSchema === format,
    );
    if (target === undefined) return undefined;
    return target[0] as TransformedStringTypeKind;
}

function schemaFetchError(base: Location | undefined, address: string): never {
    if (base === undefined) {
        return messageError("SchemaFetchErrorTopLevel", { address });
    }

    return messageError("SchemaFetchError", {
        address,
        base: base.canonicalRef,
    });
}

class Resolver {
    public constructor(
        private readonly _ctx: RunContext,
        private readonly _store: JSONSchemaStore,
        private readonly _canonizer: Canonizer,
    ) {}

    private async tryResolveVirtualRef(
        fetchBase: Location,
        lookupBase: Location,
        virtualRef: Ref,
    ): Promise<[JSONSchema | undefined, Location]> {
        let didAdd = false;
        // If we are resolving into a schema file that we haven't seen yet then
        // we don't know its $id mapping yet, which means we don't know where we
        // will end up.  What we do if we encounter a new schema is add all its
        // IDs first, and then try to canonize again.
        for (;;) {
            const loc = this._canonizer.canonize(fetchBase, virtualRef);
            const canonical = loc.canonicalRef;
            assert(
                canonical.hasAddress,
                "Canonical ref can't be resolved without an address",
            );
            const address = canonical.address;

            const schema =
                canonical.addressURI === undefined
                    ? undefined
                    : await this._store.get(
                          address,
                          this._ctx.debugPrintSchemaResolving,
                      );
            if (schema === undefined) {
                return [undefined, loc];
            }

            if (this._canonizer.addSchema(schema, address)) {
                assert(!didAdd, "We can't add a schema twice");
                didAdd = true;
            } else {
                let lookupLoc = this._canonizer.canonize(
                    lookupBase,
                    virtualRef,
                );
                if (fetchBase !== undefined) {
                    lookupLoc = new Location(
                        new Ref(
                            loc.canonicalRef.addressURI,
                            lookupLoc.canonicalRef.path,
                        ),
                        lookupLoc.virtualRef,
                        lookupLoc.haveID,
                    );
                }

                return [lookupLoc.canonicalRef.lookupRef(schema), lookupLoc];
            }
        }
    }

    public async resolveVirtualRef(
        base: Location,
        virtualRef: Ref,
    ): Promise<[JSONSchema, Location]> {
        if (this._ctx.debugPrintSchemaResolving) {
            console.log(
                `resolving ${virtualRef.toString()} relative to ${base.toString()}`,
            );
        }

        // Try with the virtual base first.  If that doesn't work, use the
        // canonical ref's address with the virtual base's path.
        let result = await this.tryResolveVirtualRef(base, base, virtualRef);
        let schema = result[0];
        if (schema !== undefined) {
            if (this._ctx.debugPrintSchemaResolving) {
                console.log(`resolved to ${result[1].toString()}`);
            }

            return [schema, result[1]];
        }

        const altBase = new Location(
            base.canonicalRef,
            new Ref(base.canonicalRef.addressURI, base.virtualRef.path),
            base.haveID,
        );
        result = await this.tryResolveVirtualRef(altBase, base, virtualRef);
        schema = result[0];
        if (schema !== undefined) {
            if (this._ctx.debugPrintSchemaResolving) {
                console.log(`resolved to ${result[1].toString()}`);
            }

            return [schema, result[1]];
        }

        return schemaFetchError(base, virtualRef.toString());
    }

    public async resolveTopLevelRef(ref: Ref): Promise<[JSONSchema, Location]> {
        return await this.resolveVirtualRef(
            new Location(new Ref(ref.addressURI, [])),
            new Ref(undefined, ref.path),
        );
    }
}

async function addTypesInSchema(
    resolver: Resolver,
    typeBuilder: TypeBuilder,
    references: ReadonlyMap<string, Ref>,
    attributeProducers: JSONSchemaAttributeProducer[],
): Promise<void> {
    const typeForCanonicalRef = new EqualityMap<Ref, TypeRef>();

    function setTypeForLocation(loc: Location, t: TypeRef): void {
        const maybeRef = typeForCanonicalRef.get(loc.canonicalRef);
        if (maybeRef !== undefined) {
            assert(
                maybeRef === t,
                "Trying to set path again to different type",
            );
        }

        typeForCanonicalRef.set(loc.canonicalRef, t);
    }

    async function makeObject(
        loc: Location,
        attributes: TypeAttributes,
        properties: StringMap,
        requiredArray: string[],
        additionalProperties: unknown,
        sortKey: (k: string) => number | string = (k: string): string =>
            k.toLowerCase(),
    ): Promise<TypeRef> {
        const required = new Set(requiredArray);
        const propertiesMap = mapSortBy(mapFromObject(properties), (_, k) =>
            sortKey(k),
        );
        const props = await mapMapSync(
            propertiesMap,
            async (propSchema, propName) => {
                const propLoc = loc.push("properties", propName);
                const t = await toType(
                    checkJSONSchema(propSchema, propLoc.canonicalRef),
                    propLoc,
                    makeNamesTypeAttributes(propName, true),
                );
                const isOptional = !required.has(propName);
                return typeBuilder.makeClassProperty(t, isOptional);
            },
        );
        let additionalPropertiesType: TypeRef | undefined;
        if (
            additionalProperties === undefined ||
            additionalProperties === true
        ) {
            additionalPropertiesType = typeBuilder.getPrimitiveType("any");
        } else if (additionalProperties === false) {
            additionalPropertiesType = undefined;
        } else {
            const additionalLoc = loc.push("additionalProperties");
            additionalPropertiesType = await toType(
                checkJSONSchema(
                    additionalProperties,
                    additionalLoc.canonicalRef,
                ),
                additionalLoc,
                singularizeTypeNames(attributes),
            );
        }

        const additionalRequired = setSubtract(required, props.keys());
        if (additionalRequired.size > 0) {
            const t = additionalPropertiesType;
            if (t === undefined) {
                return messageError(
                    "SchemaAdditionalTypesForbidRequired",
                    withRef(loc),
                );
            }

            const additionalProps = mapFromIterable(
                additionalRequired,
                (_name) => typeBuilder.makeClassProperty(t, false),
            );
            mapMergeInto(props, additionalProps);
        }

        return typeBuilder.getUniqueObjectType(
            attributes,
            props,
            additionalPropertiesType,
        );
    }

    async function convertToType(
        schema: StringMap,
        loc: Location,
        typeAttributes: TypeAttributes,
    ): Promise<TypeRef> {
        const enumArray = Array.isArray(schema.enum) ? schema.enum : undefined;
        const isConst = schema.const !== undefined;
        const typeSet = definedMap(schema.type, (t) => checkTypeList(t, loc));

        function isTypeIncluded(name: JSONSchemaType): boolean {
            if (typeSet !== undefined && !typeSet.has(name)) {
                return false;
            }

            if (enumArray !== undefined) {
                let predicate: (x: unknown) => boolean;
                switch (name) {
                    case "null":
                        predicate = (x): x is null => x === null;
                        break;
                    case "integer":
                        predicate = (x): x is number =>
                            typeof x === "number" && x === Math.floor(x);
                        break;
                    default:
                        predicate = (x): x is typeof name => typeof x === name;
                        break;
                }

                return enumArray.find(predicate) !== undefined;
            }

            if (isConst) {
                return name === (schema.type ?? typeof schema.const);
            }

            return true;
        }

        const includedTypes = setFilter(schemaTypes, isTypeIncluded);
        let producedAttributesForNoCases: JSONSchemaAttributes[] | undefined;

        function forEachProducedAttribute(
            cases: JSONSchema[] | undefined,
            f: (attributes: JSONSchemaAttributes) => void,
        ): void {
            let attributes: JSONSchemaAttributes[];
            if (
                cases === undefined &&
                producedAttributesForNoCases !== undefined
            ) {
                attributes = producedAttributesForNoCases;
            } else {
                attributes = [];
                for (const producer of attributeProducers) {
                    const newAttributes = producer(
                        schema,
                        loc.canonicalRef,
                        includedTypes,
                        cases,
                    );
                    if (newAttributes === undefined) continue;
                    attributes.push(newAttributes);
                }

                if (cases === undefined) {
                    producedAttributesForNoCases = attributes;
                }
            }

            for (const a of attributes) {
                f(a);
            }
        }

        function combineProducedAttributes(
            f: (attributes: JSONSchemaAttributes) => TypeAttributes | undefined,
        ): TypeAttributes {
            let result = emptyTypeAttributes;
            forEachProducedAttribute(undefined, (attr) => {
                const maybeAttributes = f(attr);
                if (maybeAttributes === undefined) return;
                result = combineTypeAttributes(
                    "union",
                    result,
                    maybeAttributes,
                );
            });
            return result;
        }

        function makeAttributes(attributes: TypeAttributes): TypeAttributes {
            if (schema.oneOf === undefined) {
                attributes = combineTypeAttributes(
                    "union",
                    attributes,
                    combineProducedAttributes(
                        ({ forType, forUnion, forCases }) => {
                            assert(
                                forUnion === undefined &&
                                    forCases === undefined,
                                "We can't have attributes for unions and cases if we don't have a union",
                            );
                            return forType;
                        },
                    ),
                );
            }

            return modifyTypeNames(attributes, (maybeTypeNames) => {
                const typeNames = defined(maybeTypeNames);
                if (!typeNames.areInferred) {
                    return typeNames;
                }

                let title = schema.title;
                if (typeof title !== "string") {
                    title = loc.canonicalRef.definitionName;
                }

                if (typeof title === "string") {
                    return TypeNames.make(
                        new Set([title]),
                        new Set(),
                        schema.$ref !== undefined,
                    );
                }

/**
 * Validation result type with detailed error information.
 *
 * `IValidation<T>` is the return type of `typia.validate<T>()` and related
 * validation functions. Unlike `typia.is<T>()` which returns a boolean, or
 * `typia.assert<T>()` which throws exceptions, `typia.validate<T>()` returns
 * this structured result with full error details.
 *
 * Check the {@link IValidation.success | success} discriminator:
 *
 * - `true` → {@link IValidation.ISuccess} with validated
 *   {@link IValidation.ISuccess.data | data}
 * - `false` → {@link IValidation.IFailure} with
 *   {@link IValidation.IFailure.errors | errors} array
 *
 * This is the recommended validation function when you need to report
 * validation errors to users or log them for debugging.
 *
 * @author Jeongho Nam - https://github.com/samchon
 * @example
 *   const result = typia.validate<User>(input);
 *   if (result.success) {
 *     return result.data; // User type
 *   } else {
 *     result.errors.forEach((e) => console.log(e.path, e.expected));
 *   }
 *
 * @template T The expected type after successful validation
 */
export type IValidation<T = unknown> =
  | IValidation.ISuccess<T>
  | IValidation.IFailure;

export namespace IValidation {
  /**
   * Successful validation result.
   *
   * Indicates the input matches the expected type. The validated data is
   * available in {@link data} with full type information.
   *
   * @template T The validated type
   */
  export interface ISuccess<T = unknown> {
    /**
     * Success discriminator.
     *
     * Always `true` for successful validations. Use this to narrow the type
     * before accessing {@link data}.
     */
    success: true;

    /**
     * The validated data with correct type.
     *
     * The original input after successful validation. TypeScript will narrow
     * this to type `T` when {@link success} is `true`.
     */
    data: T;
  }

  /**
   * Failed validation result with error details.
   *
   * Indicates the input did not match the expected type. Contains the original
   * data and an array of all validation errors found.
   */
  export interface IFailure {
    /**
     * Success discriminator.
     *
     * Always `false` for failed validations. Use this to narrow the type before
     * accessing {@link errors}.
     */
    success: false;

    /**
     * The original input that failed validation.
     *
     * Preserved as `unknown` type since it didn't match the expected type.
     * Useful for debugging or logging the actual value.
     */
    data: unknown;

    /**
     * Array of validation errors.
     *
     * Contains one entry for each validation failure found. Multiple errors may
     * exist if the input has multiple type mismatches.
     */
    errors: IError[];
  }

  /**
   * Detailed information about a single validation error.
   *
   * Describes exactly what went wrong during validation, including the
   * location, expected type, and actual value.
   */
  export interface IError {
    /**
     * Property path to the error location.
     *
     * A dot-notation path from the root input to the failing property. Uses
     * `$input` as the root. Example: `"$input.user.email"` or
     * `"$input.items[0].price"`.
     */
    path: string;

    /**
     * Expected type expression.
     *
     * A human-readable description of what type was expected at this location.
     * Examples: `"string"`, `"number & ExclusiveMinimum<0>"`, `"(\"active\" |
     * \"inactive\")"`.
     */
    expected: string;

    /**
     * The actual value that failed validation.
     *
     * The value found at the error path. May be `undefined` if the property was
     * missing. Useful for debugging type mismatches.
     */
    value: unknown;

    /**
     * Human-readable error description.
     *
     * Optional additional context about the validation failure, such as
     * constraint violations or custom error messages.
     */
    description?: string;
  }
}

